import math
from . import manual_probe, bed_mesh, probe
DEFAULT_SAMPLE_COUNT = 3
DEFAULT_SPEED = 50.0
DEFAULT_HORIZONTAL_MOVE_Z = 5.0

class AxisTwistCompensation:

    def __init__(self, config):
        self.printer = config.get_printer()
        self.gcode = self.printer.lookup_object("gcode")
        self.horizontal_move_z = config.getfloat("horizontal_move_z", DEFAULT_HORIZONTAL_MOVE_Z)
        self.speed = config.getfloat("speed", DEFAULT_SPEED)
        self.calibrate_start_x = config.getfloat("calibrate_start_x")
        self.calibrate_end_x = config.getfloat("calibrate_end_x")
        self.calibrate_y = config.getfloat("calibrate_y")
        self.z_compensations = config.getlists("z_compensations", default=[], parser=float)
        self.compensation_start_x = config.getfloat("compensation_start_x", default=None)
        self.compensation_end_x = config.getfloat("compensation_start_y", default=None)
        self.m = None
        self.b = None
        self.calibrater = Calibrater(self, config)
        self.printer.register_event_handler("probe:update_results", self._update_z_compensation_value)

    def _update_z_compensation_value(self, pos):
        if not self.z_compensations:
            return
        x_coord = pos[0]
        z_compensations = self.z_compensations
        sample_count = len(z_compensations)
        spacing = (self.calibrate_end_x - self.calibrate_start_x) / (sample_count - 1)
        interpolate_t = (x_coord - self.calibrate_start_x) / spacing
        interpolate_i = int(math.floor(interpolate_t))
        interpolate_i = bed_mesh.constrain(interpolate_i, 0, sample_count - 2)
        interpolate_t -= interpolate_i
        interpolated_z_compensation = bed_mesh.lerp(interpolate_t, z_compensations[interpolate_i], z_compensations[interpolate_i + 1])
        pos[2] += interpolated_z_compensation

    def clear_compensations(self):
        self.z_compensations = []
        self.m = None
        self.b = None


class Calibrater:

    def __init__(self, compensation, config):
        self.compensation = compensation
        self.printer = compensation.printer
        self.gcode = self.printer.lookup_object("gcode")
        self.probe = None
        self.lift_speed, self.probe_x_offset, self.probe_y_offset, _ = (None, None,
                                                                        None, None)
        self.printer.register_event_handler("klippy:connect", self._handle_connect)
        self.speed = compensation.speed
        self.horizontal_move_z = compensation.horizontal_move_z
        self.start_point = (compensation.calibrate_start_x,
         compensation.calibrate_y)
        self.end_point = (compensation.calibrate_end_x,
         compensation.calibrate_y)
        self.results = None
        self.current_point_index = None
        self.gcmd = None
        self.configname = config.get_name()
        self._register_gcode_handlers()

    def _handle_connect(self):
        self.probe = self.printer.lookup_object("probe", None)
        if self.probe is None:
            config = self.printer.lookup_object("configfile")
            raise config.error("AXIS_TWIST_COMPENSATION requires [probe] to be defined")
        self.lift_speed = self.probe.get_probe_params()["lift_speed"]
        self.probe_x_offset, self.probe_y_offset, _ = self.probe.get_offsets()

    def _register_gcode_handlers(self):
        self.gcode = self.printer.lookup_object("gcode")
        self.gcode.register_command("AXIS_TWIST_COMPENSATION_CALIBRATE",
          (self.cmd_AXIS_TWIST_COMPENSATION_CALIBRATE),
          desc=(self.cmd_AXIS_TWIST_COMPENSATION_CALIBRATE_help))

    cmd_AXIS_TWIST_COMPENSATION_CALIBRATE_help = "\n    Performs the x twist calibration wizard\n    Measure z probe offset at n points along the x axis,\n    and calculate x twist compensation\n    "

    def cmd_AXIS_TWIST_COMPENSATION_CALIBRATE(self, gcmd):
        self.gcmd = gcmd
        sample_count = gcmd.get_int("SAMPLE_COUNT", DEFAULT_SAMPLE_COUNT)
        if sample_count is None or sample_count < 2:
            raise self.gcmd.error("SAMPLE_COUNT to probe must be at least 2")
        self.compensation.clear_compensations()
        x_range = self.end_point[0] - self.start_point[0]
        interval_dist = x_range / (sample_count - 1)
        nozzle_points = self._calculate_nozzle_points(sample_count, interval_dist)
        probe_points = self._calculate_probe_points(nozzle_points, self.probe_x_offset, self.probe_y_offset)
        manual_probe.verify_no_manual_probe(self.printer)
        self.current_point_index = 0
        self.results = []
        self._calibration(probe_points, nozzle_points, interval_dist)

    def _calculate_nozzle_points(self, sample_count, interval_dist):
        nozzle_points = []
        for i in range(sample_count):
            x = self.start_point[0] + i * interval_dist
            y = self.start_point[1]
            nozzle_points.append((x, y))

        return nozzle_points

    def _calculate_probe_points(self, nozzle_points, probe_x_offset, probe_y_offset):
        probe_points = []
        for point in nozzle_points:
            x = point[0] - probe_x_offset
            y = point[1] - probe_y_offset
            probe_points.append((x, y))

        return probe_points

    def _move_helper(self, target_coordinates, override_speed=None):
        target_coordinates = (target_coordinates[0], target_coordinates[1], None) if len(target_coordinates) == 2 else target_coordinates
        toolhead = self.printer.lookup_object("toolhead")
        speed = self.speed if target_coordinates[2] == None else self.lift_speed
        speed = override_speed if override_speed is not None else speed
        toolhead.manual_move(target_coordinates, speed)

    def _calibration(self, probe_points, nozzle_points, interval):
        self.gcmd.respond_info("AXIS_TWIST_COMPENSATION_CALIBRATE: Probing point %d of %d" % (
         self.current_point_index + 1,
         len(probe_points)))
        self._move_helper((None, None, self.horizontal_move_z))
        self._move_helper((probe_points[self.current_point_index][0],
         probe_points[self.current_point_index][1], None))
        pos = probe.run_single_probe(self.probe, self.gcmd)
        self.current_measured_z = pos[2]
        self._move_helper((None, None, self.horizontal_move_z))
        self._move_helper(nozzle_points[self.current_point_index])
        manual_probe.ManualProbeHelper(self.printer, self.gcmd, self._manual_probe_callback_factory(probe_points, nozzle_points, interval))

    def _manual_probe_callback_factory(self, probe_points, nozzle_points, interval):
        is_end = self.current_point_index == len(probe_points) - 1

        def callback(kin_pos):
            if kin_pos is None:
                self.gcmd.respond_info("AXIS_TWIST_COMPENSATION_CALIBRATE: Probe cancelled, calibration aborted")
                return
            z_offset = self.current_measured_z - kin_pos[2]
            self.results.append(z_offset)
            if is_end:
                self._finalize_calibration()
            else:
                self.current_point_index += 1
                self._calibration(probe_points, nozzle_points, interval)

        return callback

    def _finalize_calibration(self):
        avg = sum(self.results) / len(self.results)
        self.results = [avg - x for x in self.results]
        configfile = self.printer.lookup_object("configfile")
        values_as_str = ", ".join(["{:.6f}".format(x) for x in self.results])
        configfile.set(self.configname, "z_compensations", values_as_str)
        configfile.set(self.configname, "compensation_start_x", self.start_point[0])
        configfile.set(self.configname, "compensation_end_x", self.end_point[0])
        self.compensation.z_compensations = self.results
        self.compensation.compensation_start_x = self.start_point[0]
        self.compensation.compensation_end_x = self.end_point[0]
        self.gcode.respond_info("AXIS_TWIST_COMPENSATION state has been saved for the current session.  The SAVE_CONFIG command will update the printer config file and restart the printer.")
        self.gcmd.respond_info("AXIS_TWIST_COMPENSATION_CALIBRATE: Calibration complete, offsets: %s, mean z_offset: %f" % (
         self.results, avg))


def load_config(config):
    return AxisTwistCompensation(config)

